1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Business rule: an owner's {@code ownerSegment} is {@code <TIER>_<AREA>}. TIER is {@code PREMIUM}
9	 * when {@code membershipLevel} is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when
10	 * the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. Kept as a
11	 * small, self-contained unit so the rule can be applied from the read flow without adding
12	 * complexity to the mapper, controller, or service.
13	 */
14	public final class OwnerSegmentPolicy {
15	
16	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
17	
18	    private OwnerSegmentPolicy() {
19	    }
20	
21	    /**
22	     * Derive the {@code ownerSegment} for the given owner.
23	     *
24	     * @param owner the owner whose segment to derive
25	     * @return the segment, one of the four {@code <TIER>_<AREA>} combinations
26	     */
27	    public static String ownerSegment(Owner owner) {
28	        String tier = OwnerMembershipCeilingPolicy.cappedMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
29	        String area = METRO_REGIONS.contains(OwnerLocalityPolicy.locality(owner)) ? "METRO" : "REGIONAL";
30	        return tier + "_" + area;
31	    }
32	}
