1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Business rule: on successful creation an audit line is emitted via the dedicated {@code AUDIT}
12	 * logger carrying the new owner's id, its {@code memberId}, its {@code registrationDate} and its
13	 * {@code membershipLevel}.
14	 * Kept as a small, self-contained unit so the rule can be applied from the create flow after the
15	 * owner has been saved without adding complexity to the controller or service.
16	 */
17	public final class OwnerAuditPolicy {
18	
19	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
20	
21	    /** Monotonically increasing sequence across all creates, for the structured event. */
22	    private static final AtomicLong SEQ = new AtomicLong();
23	
24	    private OwnerAuditPolicy() {
25	    }
26	
27	    /**
28	     * Emit the immutable structured {@code OWNER_CREATED} event carrying the create sequence,
29	     * the owner id, its {@code memberId} and its membership level.
30	     */
31	    static void auditCreatedEvent(Owner owner) {
32	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
33	            SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(),
34	            OwnerMembershipLevelPolicy.membershipLevel(owner));
35	    }
36	
37	    /** Emit the create audit line for a freshly saved owner. */
38	    public static void auditCreate(Owner owner) {
39	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
40	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
41	            OwnerMembershipLevelPolicy.membershipLevel(owner));
42	        auditCreatedEvent(owner);
43	    }
44	}
