1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.HashSet;
4	import java.util.Map;
5	import java.util.Set;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Business rule: on creation an owner is assigned a single {@code memberId} formatted
11	 * {@code <REGION><FY><HASH8><CHK>}, where REGION is the region code derived from the owner's
12	 * postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, else {@code UNKNOWN}), FY is the two-digit
13	 * registration-date fiscal year, HASH8 is the first eight upper-case hex characters of SHA-256 over
14	 * the normalized telephone concatenated with the last name (the same HASH8 used by the
15	 * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits of
16	 * {@code <REGION><FY><HASH8>} (e.g. {@code NSW271A2B3C4D8}). Kept as a small, self-contained unit so
17	 * the rule can be applied from the create flow without adding complexity to the controller or service.
18	 */
19	public final class OwnerMemberIdPolicy {
20	
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
23	
24	    private OwnerMemberIdPolicy() {
25	    }
26	
27	    /**
28	     * Assign the {@code memberId} for a newly created owner.
29	     *
30	     * @param clinicService source of the existing owners, for collision handling
31	     * @param owner         the owner being created
32	     */
33	    public static void assignMemberId(ClinicService clinicService, Owner owner) {
34	        String body = region(owner.getPostcode()) + fiscalYear(owner) + hash8(owner);
35	        owner.setMemberId(deduplicate(clinicService, body + luhn(body)));
36	    }
37	
38	    /** {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not already in use. */
39	    private static String deduplicate(ClinicService clinicService, String base) {
40	        Set<String> used = new HashSet<>();
41	        for (Owner existing : clinicService.findAllOwners()) {
42	            used.add(existing.getMemberId());
43	        }
44	        String candidate = base;
45	        for (int n = 2; used.contains(candidate); n++) {
46	            candidate = base + "-" + n;
47	        }
48	        return candidate;
49	    }
50	
51	    /** The region whose postcode range contains {@code postcode}, or {@code UNKNOWN}. */
52	    static String region(String postcode) {
53	        if (postcode != null) {
54	            int code = Integer.parseInt(postcode);
55	            for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
56	                int[] range = entry.getValue();
57	                if (code >= range[0] && code <= range[1]) {
58	                    return entry.getKey();
59	                }
60	            }
61	        }
62	        return "UNKNOWN";
63	    }
64	
65	    /** Two-digit registration-date fiscal year segment. */
66	    private static String fiscalYear(Owner owner) {
67	        return String.format("%02d", OwnerFiscalYearPolicy.fiscalYearOf(owner.getRegistrationDate()) % 100);
68	    }
69	
70	    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
71	    private static String hash8(Owner owner) {
72	        String input = orEmpty(owner.getTelephone()) + orEmpty(owner.getLastName());
73	        return Sha256Hex.upper(input, 4);
74	    }
75	
76	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
77	    private static int luhn(String s) {
78	        int sum = 0;
79	        boolean dbl = true;
80	        for (int i = s.length() - 1; i >= 0; i--) {
81	            char c = s.charAt(i);
82	            if (c < '0' || c > '9') {
83	                continue;
84	            }
85	            int d = c - '0';
86	            if (dbl) {
87	                d *= 2;
88	                if (d > 9) {
89	                    d -= 9;
90	                }
91	            }
92	            sum += d;
93	            dbl = !dbl;
94	        }
95	        return (10 - (sum % 10)) % 10;
96	    }
97	
98	    private static String orEmpty(String value) {
99	        return OwnerFieldNormalizer.orEmpty(value);
100	    }
101	}
