1	package org.springframework.samples.petclinic.service;
2	
3	import org.springframework.http.HttpStatus;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.web.bind.annotation.ResponseStatus;
6	
7	/**
8	 * Business rule: a household is keyed on (last name, postcode). Every owner is given a
9	 * deterministic {@code householdId} on creation &mdash; the first 12 hex characters of
10	 * SHA-256 over {@code normalizedLastName|postcode} &mdash; so owners with the same last name
11	 * and postcode share it automatically. Because they are the same household, a second such owner
12	 * is rejected unless the request opts in to sharing ({@code sharesHousehold == true}), which only
13	 * bypasses the rejection; the id is assigned either way. Kept as a small, self-contained unit so
14	 * the rule can be enforced from the create flow without adding complexity to the controller or
15	 * service.
16	 */
17	public final class OwnerHouseholdPolicy {
18	
19	    private OwnerHouseholdPolicy() {
20	    }
21	
22	    /**
23	     * Assign the owner's deterministic {@code householdId} so owners with the same (last name,
24	     * postcode) share it. Shared households are permitted &mdash; a new member simply joins, and
25	     * their membership level is capped by {@link OwnerMembershipCeilingPolicy}.
26	     *
27	     * @param clinicService   source of the existing owners (unused; kept for call-site stability)
28	     * @param owner           the owner being created
29	     * @param sharesHousehold whether the request opted in to a shared household (no longer required)
30	     */
31	    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
32	        owner.setHouseholdId(householdId(
33	            OwnerFieldNormalizer.name(owner.getLastName()), OwnerFieldNormalizer.orEmpty(owner.getPostcode())));
34	    }
35	
36	    /** Derive a stable identifier shared by every owner in the same (last name, postcode) household. */
37	    private static String householdId(String lastName, String postcode) {
38	        return Sha256Hex.lower(lastName + "|" + postcode, 6);
39	    }
40	
41	    /** Thrown when another owner already shares the same last name and postcode. */
42	    @ResponseStatus(HttpStatus.CONFLICT)
43	    public static class DuplicateHouseholdException extends RuntimeException {
44	    }
45	}
