1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = {PetMapper.class})
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.service.OwnerTelephoneDisplayPolicy.telephoneDisplay(owner))")
24	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.service.OwnerFiscalYearPolicy.fiscalYear(owner))")
25	    @Mapping(target = "membershipPoints",expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipLevelPolicy.membershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipCeilingPolicy.cappedMembershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.service.OwnerLocalityPolicy.locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.service.OwnerTimezonePolicy.timezone(owner))")
29	    @Mapping(target = "bulkSignupWarning", expression = "java(org.springframework.samples.petclinic.service.OwnerBulkSignupPolicy.bulkSignupWarning(owner))")
30	    @Mapping(target = "capacityWarning", expression = "java(org.springframework.samples.petclinic.service.OwnerCapacityWarningPolicy.capacityWarning(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.service.OwnerContactPreferencePolicy.contactPreference(owner))")
32	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.service.OwnerIdentityPolicy.identityKey(owner))")
33	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.service.OwnerAgeBandPolicy.ageBand(owner))")
34	    @Mapping(target = "selfLink", expression = "java(org.springframework.samples.petclinic.service.OwnerSelfLinkPolicy.selfLink(owner))")
35	    @Mapping(target = "ownerSegment", expression = "java(org.springframework.samples.petclinic.service.OwnerSegmentPolicy.ownerSegment(owner))")
36	    @Mapping(target = "riskFlag", expression = "java(org.springframework.samples.petclinic.service.OwnerRiskFlagPolicy.riskFlag(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
42	    @Mapping(target = "pets", ignore = true)
43	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
44	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
45	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
46	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
47	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
48	    Owner toOwner(OwnerFieldsDto ownerDto);
49	
50	    /**
51	     * Compose the stored/returned address, preferring the structured fields: when a non-blank
52	     * {@code addressLine1} is supplied it is the normalized line 1 with the normalized
53	     * {@code addressLine2} appended after a single space (when present); otherwise fall back to
54	     * the normalized flat {@code address} for backward compatibility.
55	     */
56	    default String composeAddress(OwnerFieldsDto ownerDto) {
57	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
58	        if (line1 == null || line1.isBlank()) {
59	            return normalizeAddress(ownerDto.getAddress());
60	        }
61	        String line2 = normalizeAddress(ownerDto.getAddressLine2());
62	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
63	    }
64	
65	    /**
66	     * Canonicalise the address on create: trim, collapse whitespace runs, upper-case, and expand
67	     * the common street-type abbreviations. The normalized value is what gets stored, returned, and
68	     * compared by the household rules.
69	     */
70	    @Named("normalizeAddress")
71	    default String normalizeAddress(String address) {
72	        if (address == null) {
73	            return null;
74	        }
75	        return address.trim().replaceAll("\\s+", " ").toUpperCase()
76	            .replaceAll("\\bST\\b", "STREET")
77	            .replaceAll("\\bRD\\b", "ROAD")
78	            .replaceAll("\\bAVE\\b", "AVENUE");
79	    }
80	
81	    /** Store the telephone in E.164 form (see {@link E164Telephone#toE164}). */
82	    @Named("normalizeTelephone")
83	    default String normalizeTelephone(String telephone) {
84	        return E164Telephone.toE164(telephone);
85	    }
86	
87	    /** Lower-case the email so it is stored and returned in canonical form. */
88	    @Named("normalizeEmail")
89	    default String normalizeEmail(String email) {
90	        return email == null ? null : email.toLowerCase();
91	    }
92	
93	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
94	
95	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
96	
97	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
98	        OwnerPageDto ownerPageDto = new OwnerPageDto();
99	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
100	        ownerPageDto.setPage(ownerPage.getNumber());
101	        ownerPageDto.setSize(ownerPage.getSize());
102	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
103	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
104	        return ownerPageDto;
105	    }
106	}
