1	package org.springframework.samples.petclinic.service;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Business rule: an owner's {@code locality} is the REGION component of its {@code memberId} (the
7	 * leading letters before the fiscal-year digits in {@code <REGION><FY><HASH8><CHK>}), or
8	 * {@code UNKNOWN} when no member id has been assigned yet. Kept as a small, self-contained unit so the
9	 * rule can be applied from the read flow without adding complexity to the mapper, controller, or service.
10	 */
11	public final class OwnerLocalityPolicy {
12	
13	    private OwnerLocalityPolicy() {
14	    }
15	
16	    /**
17	     * Derive the {@code locality} for the given owner from its member id's region component.
18	     *
19	     * @param owner the owner whose locality to derive
20	     * @return the REGION portion of the member id, or {@code "UNKNOWN"} when it is not set
21	     */
22	    public static String locality(Owner owner) {
23	        String id = owner.getMemberId();
24	        if (id == null) {
25	            return "UNKNOWN";
26	        }
27	        int end = 0;
28	        while (end < id.length() && Character.isLetter(id.charAt(end))) {
29	            end++;
30	        }
31	        return id.substring(0, end);
32	    }
33	}
