1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Business rule: an owner's {@code timezone} is the IANA name mapped from its
9	 * {@code locality} region via a fixed region-to-timezone table (NSW->Australia/Sydney,
10	 * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region is
11	 * not in the table. Kept as a small, self-contained unit alongside
12	 * {@link OwnerLocalityPolicy} so the rule can be applied from the read flow without adding
13	 * complexity to the mapper, controller, or service.
14	 */
15	public final class OwnerTimezonePolicy {
16	
17	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
18	        "NSW", "Australia/Sydney",
19	        "VIC", "Australia/Melbourne",
20	        "QLD", "Australia/Brisbane");
21	
22	    private OwnerTimezonePolicy() {
23	    }
24	
25	    /**
26	     * Derive the IANA {@code timezone} for the given owner from its locality region.
27	     *
28	     * @param owner the owner whose timezone to derive
29	     * @return the IANA timezone name, or {@code null} when the region has no mapping
30	     */
31	    public static String timezone(Owner owner) {
32	        return REGION_TIMEZONE.get(OwnerLocalityPolicy.locality(owner));
33	    }
34	}
