1	package org.springframework.samples.petclinic.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Shared SHA-256 hex encoding: the leading {@code bytes} bytes of {@code SHA-256(input)} rendered
9	 * as lower- or upper-case hexadecimal. Extracted so the several identity, household and customer-code
10	 * policies share one implementation instead of each repeating the digest-and-format loop.
11	 */
12	final class Sha256Hex {
13	
14	    private Sha256Hex() {
15	    }
16	
17	    /** Lower-case hex of the leading {@code bytes} bytes of {@code SHA-256(input)}. */
18	    static String lower(String input, int bytes) {
19	        return hex(input, bytes, "%02x");
20	    }
21	
22	    /** Upper-case hex of the leading {@code bytes} bytes of {@code SHA-256(input)}. */
23	    static String upper(String input, int bytes) {
24	        return hex(input, bytes, "%02X");
25	    }
26	
27	    private static String hex(String input, int bytes, String format) {
28	        try {
29	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
30	            StringBuilder sb = new StringBuilder(bytes * 2);
31	            for (int i = 0; i < bytes; i++) {
32	                sb.append(String.format(format, digest[i]));
33	            }
34	            return sb.toString();
35	        }
36	        catch (NoSuchAlgorithmException e) {
37	            throw new IllegalStateException(e);
38	        }
39	    }
40	}
