1	package org.springframework.samples.petclinic.service;
2	
3	/**
4	 * Shared canonicalisation of the owner fields the identity, household and duplicate rules key on.
5	 * Extracted so every policy normalises a given field identically instead of repeating the same
6	 * null-guard and regex in each class.
7	 */
8	final class OwnerFieldNormalizer {
9	
10	    private OwnerFieldNormalizer() {
11	    }
12	
13	    /** Telephone reduced to its digits ({@code null} &rarr; {@code ""}). */
14	    static String telephone(String telephone) {
15	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
16	    }
17	
18	    /** Email lower-cased ({@code null} &rarr; {@code ""}). */
19	    static String email(String email) {
20	        return email == null ? "" : email.toLowerCase();
21	    }
22	
23	    /** Name trimmed, internal whitespace collapsed to a single space and lower-cased
24	     *  ({@code null} &rarr; {@code ""}). */
25	    static String name(String value) {
26	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
27	    }
28	
29	    /** {@code value}, or {@code ""} when {@code null}. */
30	    static String orEmpty(String value) {
31	        return value == null ? "" : value;
32	    }
33	}
