5	/**
6	 * Adopts an existing household's derived {@code householdId} when a new owner knowingly opts into a
7	 * shared household and another owner with the same normalized (last name, address) already exists.
8	 * Extracted from {@link OwnerIdentityPolicy} so the identity-key rule stays focused purely on the
9	 * identity key and its duplicate check.
10	 */
11	final class SharedHouseholdIdAssignment {
12	
13	    private SharedHouseholdIdAssignment() {
14	    }
15	
16	    /** Adopt the existing household's id when sharing was opted in and a matching owner already exists. */
17	    static void assign(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
18	        if (!Boolean.TRUE.equals(sharesHousehold)) {
19	            return;
20	        }
21	        String lastName = OwnerFieldNormalizer.name(owner.getLastName());
22	        String address = OwnerFieldNormalizer.name(owner.getAddress());
23	        for (Owner existing : clinicService.findAllOwners()) {
24	            if (!existing.getId().equals(owner.getId())
25	                && lastName.equals(OwnerFieldNormalizer.name(existing.getLastName()))
26	                && address.equals(OwnerFieldNormalizer.name(existing.getAddress()))) {
27	                owner.setHouseholdId(householdId(lastName, address));
28	                return;
29	            }
30	        }
31	    }
32	
33	    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
34	    private static String householdId(String lastName, String address) {
35	        return Sha256Hex.lower(lastName + "|" + address, 8);
36	    }
37	}
