package org.springframework.samples.petclinic.service;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: on creation an owner is assigned a single {@code memberId} formatted
 * {@code <REGION><FY><HASH8><CHK>}, where REGION is the region code derived from the owner's
 * postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, else {@code UNKNOWN}), FY is the two-digit
 * registration-date fiscal year, HASH8 is the first eight upper-case hex characters of SHA-256 over
 * the normalized telephone concatenated with the last name (the same HASH8 used by the
 * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits of
 * {@code <REGION><FY><HASH8>} (e.g. {@code NSW271A2B3C4D8}). Kept as a small, self-contained unit so
 * the rule can be applied from the create flow without adding complexity to the controller or service.
 */
public final class OwnerMemberIdPolicy {

    private static final Map<String, int[]> REGION_RANGE = Map.of(
        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private OwnerMemberIdPolicy() {
    }

    /**
     * Assign the {@code memberId} for a newly created owner.
     *
     * @param clinicService source of the existing owners, for collision handling
     * @param owner         the owner being created
     */
    public static void assignMemberId(ClinicService clinicService, Owner owner) {
        String body = region(owner.getPostcode()) + fiscalYear(owner) + hash8(owner);
        owner.setMemberId(deduplicate(clinicService, body + luhn(body)));
    }

    /** {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not already in use. */
    private static String deduplicate(ClinicService clinicService, String base) {
        Set<String> used = new HashSet<>();
        for (Owner existing : clinicService.findAllOwners()) {
            used.add(existing.getMemberId());
        }
        String candidate = base;
        for (int n = 2; used.contains(candidate); n++) {
            candidate = base + "-" + n;
        }
        return candidate;
    }

    /** The region whose postcode range contains {@code postcode}, or {@code UNKNOWN}. */
    static String region(String postcode) {
        if (postcode != null) {
            int code = Integer.parseInt(postcode);
            for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
                int[] range = entry.getValue();
                if (code >= range[0] && code <= range[1]) {
                    return entry.getKey();
                }
            }
        }
        return "UNKNOWN";
    }

    /** Two-digit registration-date fiscal year segment. */
    private static String fiscalYear(Owner owner) {
        return String.format("%02d", OwnerFiscalYearPolicy.fiscalYearOf(owner.getRegistrationDate()) % 100);
    }

    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
    private static String hash8(Owner owner) {
        String input = orEmpty(owner.getTelephone()) + orEmpty(owner.getLastName());
        return Sha256Hex.upper(input, 4);
    }

    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
    private static int luhn(String s) {
        int sum = 0;
        boolean dbl = true;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    private static String orEmpty(String value) {
        return OwnerFieldNormalizer.orEmpty(value);
    }
}

package org.springframework.samples.petclinic.service;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: a household is keyed on (last name, postcode). Every owner is given a
 * deterministic {@code householdId} on creation &mdash; the first 12 hex characters of
 * SHA-256 over {@code normalizedLastName|postcode} &mdash; so owners with the same last name
 * and postcode share it automatically. Because they are the same household, a second such owner
 * is rejected unless the request opts in to sharing ({@code sharesHousehold == true}), which only
 * bypasses the rejection; the id is assigned either way. Kept as a small, self-contained unit so
 * the rule can be enforced from the create flow without adding complexity to the controller or
 * service.
 */
public final class OwnerHouseholdPolicy {

    private OwnerHouseholdPolicy() {
    }

    /**
     * Assign the owner's deterministic {@code householdId} so owners with the same (last name,
     * postcode) share it. Shared households are permitted &mdash; a new member simply joins, and
     * their membership level is capped by {@link OwnerMembershipCeilingPolicy}.
     *
     * @param clinicService   source of the existing owners (unused; kept for call-site stability)
     * @param owner           the owner being created
     * @param sharesHousehold whether the request opted in to a shared household (no longer required)
     */
    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
        owner.setHouseholdId(householdId(
            OwnerFieldNormalizer.name(owner.getLastName()), OwnerFieldNormalizer.orEmpty(owner.getPostcode())));
    }

    /** Derive a stable identifier shared by every owner in the same (last name, postcode) household. */
    private static String householdId(String lastName, String postcode) {
        return Sha256Hex.lower(lastName + "|" + postcode, 6);
    }

    /** Thrown when another owner already shares the same last name and postcode. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateHouseholdException extends RuntimeException {
    }
}

package org.springframework.samples.petclinic.service;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: every owner is identified by a single derived {@code identityKey}: the SHA-256
 * hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}. On creation an owner is
 * rejected only when its identityKey exactly matches an existing (non-deleted) owner's. Because the
 * telephone is part of the key, two owners with the same last name and postcode but DIFFERENT
 * telephones have different identityKeys and are both created — the second is flagged a soft match
 * by {@link OwnerPossibleDuplicatePolicy} rather than rejected. Kept as a small, self-contained unit
 * so the rule can be enforced from the create flow without adding complexity to the controller or
 * service.
 *
 * <p>Field canonicalisation is delegated to {@link OwnerFieldNormalizer} and the surname's phonetic
 * code to {@link Soundex}, keeping this class focused on the identity key itself.
 */
public final class OwnerIdentityPolicy {

    private OwnerIdentityPolicy() {
    }

    /**
     * Reject the owner when its identityKey matches any existing non-deleted owner's; otherwise flag
     * it as a possible duplicate when it soft-matches one (see {@link OwnerPossibleDuplicatePolicy}).
     *
     * @param clinicService source of the existing owners
     * @param owner         the owner being created
     * @throws DuplicateIdentityException if the identityKey is already in use
     */
    public static void rejectDuplicateIdentity(ClinicService clinicService, Owner owner) {
        String key = identityKey(owner);
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.isDeleted() && !existing.getId().equals(owner.getId())
                && key.equals(identityKey(existing))) {
                throw new DuplicateIdentityException();
            }
        }
        OwnerPossibleDuplicatePolicy.assignPossibleDuplicate(clinicService, owner);
    }

    /** The owner's derived identity key: SHA-256 hex of {@code telephone|email|soundex(lastName)}. */
    public static String identityKey(Owner owner) {
        return Sha256Hex.lower(OwnerFieldNormalizer.telephone(owner.getTelephone()) + "|"
            + OwnerFieldNormalizer.email(owner.getEmail()) + "|"
            + Soundex.of(owner.getLastName()), 32);
    }

    /** Thrown when another owner already has the same identityKey. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateIdentityException extends RuntimeException {
    }
}

