package org.springframework.samples.petclinic.service;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: an owner's {@code locality} is the REGION component of its {@code memberId} (the
 * leading letters before the fiscal-year digits in {@code <REGION><FY><HASH8><CHK>}), or
 * {@code UNKNOWN} when no member id has been assigned yet. Kept as a small, self-contained unit so the
 * rule can be applied from the read flow without adding complexity to the mapper, controller, or service.
 */
public final class OwnerLocalityPolicy {

    private OwnerLocalityPolicy() {
    }

    /**
     * Derive the {@code locality} for the given owner from its member id's region component.
     *
     * @param owner the owner whose locality to derive
     * @return the REGION portion of the member id, or {@code "UNKNOWN"} when it is not set
     */
    public static String locality(Owner owner) {
        String id = owner.getMemberId();
        if (id == null) {
            return "UNKNOWN";
        }
        int end = 0;
        while (end < id.length() && Character.isLetter(id.charAt(end))) {
            end++;
        }
        return id.substring(0, end);
    }
}

package org.springframework.samples.petclinic.service;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: on successful creation an audit line is emitted via the dedicated {@code AUDIT}
 * logger carrying the new owner's id, its {@code memberId}, its {@code registrationDate} and its
 * {@code membershipLevel}.
 * Kept as a small, self-contained unit so the rule can be applied from the create flow after the
 * owner has been saved without adding complexity to the controller or service.
 */
public final class OwnerAuditPolicy {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /** Monotonically increasing sequence across all creates, for the structured event. */
    private static final AtomicLong SEQ = new AtomicLong();

    private OwnerAuditPolicy() {
    }

    /**
     * Emit the immutable structured {@code OWNER_CREATED} event carrying the create sequence,
     * the owner id, its {@code memberId} and its membership level.
     */
    static void auditCreatedEvent(Owner owner) {
        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
            SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(),
            OwnerMembershipLevelPolicy.membershipLevel(owner));
    }

    /** Emit the create audit line for a freshly saved owner. */
    public static void auditCreate(Owner owner) {
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            OwnerMembershipLevelPolicy.membershipLevel(owner));
        auditCreatedEvent(owner);
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.Named;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = {PetMapper.class})
public interface OwnerMapper {

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.service.OwnerTelephoneDisplayPolicy.telephoneDisplay(owner))")
    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.service.OwnerFiscalYearPolicy.fiscalYear(owner))")
    @Mapping(target = "membershipPoints",expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipLevelPolicy.membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipCeilingPolicy.cappedMembershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.service.OwnerLocalityPolicy.locality(owner))")
    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.service.OwnerTimezonePolicy.timezone(owner))")
